      <Button className="self-start" onClick={() => setOpen(true)} size="sm">
        Confirm instructions were sent
      </Button>
      <AlertDialog onOpenChange={(next) => !pending && setOpen(next)} open={open}>
        <AlertDialogContent>
          <AlertDialogHeader>
