export function rejectionMessage(reason: string) {
  return `Your Workspace signup request was not approved. Reason: ${reason}`;
}

export async function captureRejectionNotification(id: string, database = getDb) {
  return database().transaction(async (tx) => {
    const [request] = await tx
      .update(signupRequest)
      .set({ status: "rejection_pending_notification" })
      .where(
        and(eq(signupRequest.id, id), eq(signupRequest.status, "rejection_pending_notification")),
      )
      .returning({
        id: signupRequest.id,
        contactEmail: signupRequest.contactEmail,
        rejectionReason: signupRequest.rejectionReason,
      });
    if (!request?.rejectionReason) return undefined;

    await tx.insert(mailMessage).values({
      signupRequestId: request.id,
      to: request.contactEmail,
      subject: "Your Workspace signup request",
      text: rejectionMessage(request.rejectionReason),
    });
    const [completed] = await tx
      .update(signupRequest)
      .set({ status: "rejected" })
      .where(
        and(eq(signupRequest.id, id), eq(signupRequest.status, "rejection_pending_notification")),
      )
      .returning(reviewRequestFields);
    return completed;
  });
}

// Reviewer notices carry no applicant information, only a link to the queue.
export function reviewerNoticeMessage(appUrl: string, text: string) {
  return `${text} Review queue: ${new URL("/review", appUrl)}`;
}

// Writes a captured message to the reviewer notification group. Returns false when it cannot.
export async function captureReviewerMail(
  signupRequestId: string,
  subject: string,
  text: string,
  target: Pick<ReturnType<typeof getDb>, "insert"> = getDb(),
) {
  const group = process.env.REVIEWER_NOTIFICATION_GROUP;
  const appUrl = process.env.APP_URL;
  if (process.env.MAIL_CAPTURE !== "true" || !group || !appUrl) return false;
  await target
    .insert(mailMessage)
    .values({ signupRequestId, to: group, subject, text: reviewerNoticeMessage(appUrl, text) });
  return true;
}

