    db.select().from(mailMessage).where(eq(mailMessage.signupRequestId, id));
  const row = async (id: string) =>
    (await db.select().from(signupRequest).where(eq(signupRequest.id, id)))[0];

  try {
    // One minimal notice per verified request, however often or concurrently it is sent.
    const verified = await seed("verified");
    const outcomes = await Promise.all([
      sendReviewerNotification(verified),
      sendReviewerNotification(verified),
    ]);
    assert.deepEqual(outcomes.sort(), ["sent", "skipped"]);
    assert.equal(await sendReviewerNotification(verified), "skipped");
    const notices = await mail(verified);
    assert.equal(notices.length, 1);
    assert.equal(notices[0].to, "reviewers@example.org");
    assert.match(notices[0].text, /http:\/\/localhost:3000\/review/);
    for (const personal of ["Secret", "Applicant", "+49 1234", "@example.test"])
      assert.ok(!notices[0].subject.includes(personal) && !notices[0].text.includes(personal));
    assert.equal((await row(verified)).reviewerNotificationState, "sent");

    // A delivery failure leaves the request verified and retryable.
    const failing = await seed("verified");
    env.MAIL_CAPTURE = "false";
    assert.equal(await sendReviewerNotification(failing), "failed");
    assert.equal((await row(failing)).status, "verified");
    assert.equal((await row(failing)).reviewerNotificationState, "failed");
    assert.equal((await mail(failing)).length, 0);
    env.MAIL_CAPTURE = "true";
    assert.equal(await sendReviewerNotification(failing), "sent");
    assert.equal((await mail(failing)).length, 1);
  );
  if (adminEmail) adminUrl.searchParams.set("authuser", adminEmail);
  const [open, setOpen] = useState(false);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string>();

  async function confirm() {
    setPending(true);
    setError(undefined);
    try {
      const { ok, result } = await post(
        `/api/review/requests/${encodeURIComponent(requestId)}/handover`,
      );
      if (ok && result.progress) {
        setOpen(false);
        onProgress(result.progress);
      } else setError(result.error ?? "The handover could not be confirmed. Please try again.");
    } catch {
      setError("The handover could not be confirmed. Please try again.");
    } finally {
      setPending(false);
    }
  }

  return (
    <div className="flex flex-col gap-3">
      <Alert>
        <CircleAlertIcon />
        <AlertTitle>Send first-login instructions in the Admin console</AlertTitle>
        <AlertDescription>
          <ol className="list-decimal pl-4">
            <li>
              Open the{" "}
              <a
                className="inline-flex items-center gap-1 underline"
                href={adminUrl.href}
                rel="noreferrer"
                target="_blank"
              >
                Admin console user page <ExternalLinkIcon className="size-3" />
              </a>{" "}
              for {email}.
            </li>
            <li>Choose Reset password and require a password change at next sign-in.</li>
            <li>Choose the option to email the instructions to the applicant.</li>
            <li>Return here and confirm. The application never sends or stores the password.</li>
          </ol>
        </AlertDescription>
      </Alert>
      <Button className="self-start" onClick={() => setOpen(true)} size="sm">
        Confirm instructions were sent
      </Button>
      <AlertDialog onOpenChange={(next) => !pending && setOpen(next)} open={open}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Confirm the instructions were sent?</AlertDialogTitle>
            <AlertDialogDescription>
              This records that first-login instructions were sent for {email}. It does not show
              that the message was delivered or that the applicant has signed in.
            </AlertDialogDescription>
          </AlertDialogHeader>
          {error && (
            <p className="text-sm text-destructive" role="alert">
              {error}
            </p>
          )}
          <AlertDialogFooter>
            <AlertDialogCancel disabled={pending}>Cancel</AlertDialogCancel>
            <AlertDialogAction disabled={pending} onClick={() => void confirm()}>
              {pending && <Spinner data-icon="inline-start" />}
              Confirm handover
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
  return request;
}

export function rejectionMessage(reason: string) {
  return `Your Workspace signup request was not approved. Reason: ${reason}`;
}

export async function captureRejectionNotification(id: string, database = getDb) {
  return database().transaction(async (tx) => {
    const [request] = await tx
      .update(signupRequest)
      .set({ status: "rejection_pending_notification" })
      .where(
        and(eq(signupRequest.id, id), eq(signupRequest.status, "rejection_pending_notification")),
      )
      .returning({
        id: signupRequest.id,
        contactEmail: signupRequest.contactEmail,
        rejectionReason: signupRequest.rejectionReason,
      });
    if (!request?.rejectionReason) return undefined;

    await tx.insert(mailMessage).values({
      signupRequestId: request.id,
      to: request.contactEmail,
      subject: "Your Workspace signup request",
      text: rejectionMessage(request.rejectionReason),
    });
    const [completed] = await tx
      .update(signupRequest)
      .set({ status: "rejected" })
      .where(
        and(eq(signupRequest.id, id), eq(signupRequest.status, "rejection_pending_notification")),
      )
      .returning(reviewRequestFields);
    return completed;
  });
}

// Reviewer notices carry no applicant information, only a link to the queue.
export function reviewerNoticeMessage(appUrl: string, text: string) {
  return `${text} Review queue: ${new URL("/review", appUrl)}`;
}

// Writes a captured message to the reviewer notification group. Returns false when it cannot.
export async function captureReviewerMail(
  signupRequestId: string,
  subject: string,
  text: string,
  target: Pick<ReturnType<typeof getDb>, "insert"> = getDb(),
) {
  const group = process.env.REVIEWER_NOTIFICATION_GROUP;
  const appUrl = process.env.APP_URL;
  if (process.env.MAIL_CAPTURE !== "true" || !group || !appUrl) return false;
  await target
    .insert(mailMessage)
    .values({ signupRequestId, to: group, subject, text: reviewerNoticeMessage(appUrl, text) });
  return true;
}

